import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { createClient } from '@supabase/supabase-js';
import {
  LayoutDashboard, BookOpen, CalendarCheck, ClipboardList, FolderOpen, NotebookPen,
  GraduationCap, Settings, LogOut, Plus, Search, Bell, Menu, X, ChevronRight,
  ChevronDown, Clock, AlertTriangle, CheckCircle2, Circle, FileText, Upload,
  Download, Trash2, Pencil, CalendarDays, ArrowUpRight, BookMarked, Paperclip,
  UserRound, LockKeyhole, Sparkles, LoaderCircle, Filter, ExternalLink
} from 'lucide-react';
import './styles.css';

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
const supabase = supabaseUrl && supabaseKey ? createClient(supabaseUrl, supabaseKey) : null;

const COURSE_COLORS = ['#702d43','#9b6b7b','#8b6c9c','#4f7d78','#b27b4c','#536b94'];
const DAYS = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const STATUS = {
  present: { label: 'Hadir', cls: 'green' },
  absent: { label: 'Alpa', cls: 'red' },
  excused: { label: 'Izin', cls: 'amber' },
  sick: { label: 'Sakit', cls: 'blue' },
};
const TASK_STATUS = {
  todo: { label: 'Belum dikerjakan', cls: 'muted' },
  doing: { label: 'Sedang dikerjakan', cls: 'amber' },
  done: { label: 'Selesai', cls: 'blue' },
  submitted: { label: 'Sudah dikumpulkan', cls: 'green' },
};
const fmtDate = (d) => d ? new Date(`${d}T00:00:00`).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}) : 'Belum ditentukan';
const today = () => new Date().toISOString().slice(0,10);
const getErr = (e) => e?.message || 'Terjadi kesalahan. Coba lagi.';
function App() {
  const [session, setSession] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [authMode, setAuthMode] = useState('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [authError, setAuthError] = useState('');
  const [authNotice, setAuthNotice] = useState('');
  const [page, setPage] = useState('dashboard');
  const [activeCourse, setActiveCourse] = useState(null);
  const [courseTab, setCourseTab] = useState('overview');
  const [mobileNav, setMobileNav] = useState(false);
  const [loading, setLoading] = useState(false);
  const [notice, setNotice] = useState('');
  const [semester, setSemester] = useState(null);
  const [semesters, setSemesters] = useState([]);
  const [courses, setCourses] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [materials, setMaterials] = useState([]);
  const [notes, setNotes] = useState([]);
  const [grades, setGrades] = useState([]);
  const [search, setSearch] = useState('');
  const [modal, setModal] = useState(null);

  useEffect(() => {
    if (!supabase) { setAuthLoading(false); return; }
    supabase.auth.getSession().then(({data}) => { setSession(data.session); setAuthLoading(false); });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, s) => setSession(s));
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => { if (session?.user) loadAll(); }, [session?.user?.id]);

  async function authSubmit(e) {
    e.preventDefault(); setAuthError(''); setAuthNotice('');
    if (!supabase) return setAuthError('Supabase belum dikonfigurasi. Isi environment variables sesuai README.');
    setLoading(true);
    try {
      if (authMode === 'signup') {
        const { data, error } = await supabase.auth.signUp({ email, password });
        if (error) throw error;
        if (!data.session) setAuthNotice('Akun dibuat. Cek email untuk verifikasi, lalu masuk.');
        else setAuthNotice('Akun berhasil dibuat.');
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
      }
    } catch (e) { setAuthError(getErr(e)); } finally { setLoading(false); }
  }

  async function loadAll() {
    setLoading(true); setNotice('');
    try {
      const uid = session.user.id;
      let { data: sems, error: se } = await supabase.from('semesters').select('*').eq('user_id',uid).order('created_at');
      if (se) throw se;
      let current = sems?.find(s => s.is_active) || null;
      setSemester(current);
      setSemesters(sems || []);
      const queries = await Promise.all([
        current ? supabase.from('courses').select('*').eq('user_id',uid).eq('semester_id',current.id).order('created_at') : Promise.resolve({data:[],error:null}),
        supabase.from('attendance').select('*').eq('user_id',uid).order('meeting_date',{ascending:false}),
        supabase.from('tasks').select('*').eq('user_id',uid).order('due_date',{ascending:true,nullsFirst:false}),
        supabase.from('materials').select('*').eq('user_id',uid).order('created_at',{ascending:false}),
        supabase.from('notes').select('*').eq('user_id',uid).order('updated_at',{ascending:false}),
        supabase.from('grades').select('*').eq('user_id',uid).order('created_at',{ascending:false})
      ]);
      queries.forEach(q => { if(q.error) throw q.error; });
      setCourses(queries[0].data||[]); setAttendance(queries[1].data||[]); setTasks(queries[2].data||[]);
      setMaterials(queries[3].data||[]); setNotes(queries[4].data||[]); setGrades(queries[5].data||[]);
    } catch (e) { setNotice(`Belum bisa memuat data: ${getErr(e)}`); }
    finally { setLoading(false); }
  }

  async function signOut() { await supabase.auth.signOut(); setCourses([]); setAttendance([]); setTasks([]); }
  async function saveRow(table, payload, id=null) {
    const full = {...payload, user_id:session.user.id};
    const q = id ? supabase.from(table).update(full).eq('id',id).select().single() : supabase.from(table).insert(full).select().single();
    const {data,error} = await q; if(error) throw error; return data;
  }
  async function deleteRow(table,id) { const {error}=await supabase.from(table).delete().eq('id',id); if(error) throw error; }
  function msg(text) { setNotice(text); window.setTimeout(()=>setNotice(''),4500); }
  async function handleModalSubmit(formData) {
    setLoading(true);
    try {
      const uid = session.user.id;
      if (modal.type === 'course') {
        if (!semester) throw new Error('Buat atau pilih semester aktif terlebih dahulu melalui menu Kelola Semester.');
        const row = await saveRow('courses',{semester_id:semester.id,name:formData.name.trim(),lecturer:formData.lecturer||null,room:formData.room||null,day_of_week:formData.day_of_week===''?null:Number(formData.day_of_week),start_time:formData.start_time||null,end_time:formData.end_time||null,color:formData.color||COURSE_COLORS[courses.length%COURSE_COLORS.length]},modal.row?.id);
        setCourses(prev=>modal.row?prev.map(x=>x.id===row.id?row:x):[...prev,row]);
      } else if (modal.type === 'task') {
        const row = await saveRow('tasks',{course_id:formData.course_id,title:formData.title.trim(),description:formData.description||null,due_date:formData.due_date||null,priority:formData.priority||'medium',status:formData.status||'todo'},modal.row?.id);
        setTasks(prev=>modal.row?prev.map(x=>x.id===row.id?row:x):[row,...prev]);
      } else if (modal.type === 'attendance') {
        const payload={course_id:formData.course_id,meeting_date:formData.meeting_date,status:formData.status,meeting_number:formData.meeting_number?Number(formData.meeting_number):null,note:formData.note||null};
        const existing=attendance.find(a=>a.course_id===payload.course_id&&a.meeting_date===payload.meeting_date);
        const row=await saveRow('attendance',payload,existing?.id||modal.row?.id);
        setAttendance(prev=>existing||modal.row?prev.map(a=>a.id===row.id?row:a):[row,...prev]);
      } else if (modal.type === 'note') {
        const row=await saveRow('notes',{course_id:formData.course_id,title:formData.title.trim(),content:formData.content||''},modal.row?.id);
        setNotes(prev=>modal.row?prev.map(x=>x.id===row.id?row:x):[row,...prev]);
      } else if (modal.type === 'grade') {
        const row=await saveRow('grades',{course_id:formData.course_id,title:formData.title.trim(),score:formData.score===''?null:Number(formData.score),weight:formData.weight===''?null:Number(formData.weight),note:formData.note||null},modal.row?.id);
        setGrades(prev=>modal.row?prev.map(x=>x.id===row.id?row:x):[row,...prev]);
      } else if (modal.type === 'material') {
        const externalUrl=(formData.material_url||'').trim();
        if (!formData.file && !externalUrl) throw new Error('Pilih file materi atau masukkan link materi terlebih dahulu.');
        if (externalUrl && !/^https?:\/\//i.test(externalUrl)) throw new Error('Link harus diawali https:// atau http://.');
        if (formData.file && formData.file.size > 20*1024*1024) throw new Error('Ukuran file maksimal 20 MB.');
        let path=null, fileName=null, mimeType=null;
        if (formData.file) {
          const safeName=formData.file.name.replace(/[^a-zA-Z0-9._-]/g,'_');
          path=`${uid}/${formData.course_id}/${Date.now()}-${safeName}`;
          const {error:uploadError}=await supabase.storage.from('campus-files').upload(path,formData.file,{upsert:false,contentType:formData.file.type||'application/octet-stream'});
          if(uploadError) throw uploadError;
          fileName=formData.file.name; mimeType=formData.file.type||null;
        }
        const row=await saveRow('materials',{course_id:formData.course_id,title:formData.title.trim(),description:formData.description||null,meeting_number:formData.meeting_number?Number(formData.meeting_number):null,material_date:formData.material_date||null,file_name:fileName,file_path:path,mime_type:mimeType,material_url:externalUrl||null});
        setMaterials(prev=>[row,...prev]);
      } else if (modal.type === 'semester') {
        const {error:offErr}=await supabase.from('semesters').update({is_active:false}).eq('user_id',uid);
        if(offErr) throw offErr;
        const {data,error}=await supabase.from('semesters').insert({user_id:uid,name:formData.name.trim(),absence_limit:Number(formData.absence_limit||3),start_date:formData.start_date||null,end_date:formData.end_date||null,is_active:true}).select().single();
        if(error) throw error;
        setSemester(data); setSemesters(prev=>[...prev.map(x=>({...x,is_active:false})),data]); setCourses([]); setAttendance([]); setTasks([]); setMaterials([]); setNotes([]); setGrades([]);
      }
      setModal(null); msg('Berhasil disimpan.');
    } catch(e) { msg(`Gagal menyimpan: ${getErr(e)}`); }
    finally { setLoading(false); }
  }

  async function removeItem(table,id,collection,setter,label) {
    if(!window.confirm(`Hapus ${label} ini? Tindakan ini tidak bisa dibatalkan.`)) return;
    try { await deleteRow(table,id); setter(collection.filter(x=>x.id!==id)); msg(`${label} dihapus.`); }
    catch(e) { msg(`Gagal menghapus: ${getErr(e)}`); }
  }

  async function uploadMaterialFile(material) {
    if (material.material_url) { window.open(material.material_url,'_blank','noopener,noreferrer'); return; }
    if (!material.file_path) return msg('Materi ini tidak memiliki file atau link.');
    const {data,error}=await supabase.storage.from('campus-files').createSignedUrl(material.file_path,60*10);
    if(error) return msg(`Tidak bisa membuka file: ${getErr(error)}`);
    window.open(data.signedUrl,'_blank','noopener,noreferrer');
  }

  const currentCourse = courses.find(c=>c.id===activeCourse);
  const courseAttendance = (id)=>attendance.filter(a=>a.course_id===id);
  const absenceCount = (id)=>courseAttendance(id).filter(a=>['absent','excused'].includes(a.status)).length;
  const courseTasks = (id)=>tasks.filter(t=>t.course_id===id);
  const courseMaterials = (id)=>materials.filter(m=>m.course_id===id);
  const courseNotes = (id)=>notes.filter(n=>n.course_id===id);
  const courseGrades = (id)=>grades.filter(g=>g.course_id===id);
  const pendingTasks = tasks.filter(t=>!['done','submitted'].includes(t.status));
  const overdueTasks = pendingTasks.filter(t=>t.due_date && t.due_date<today());
  const dueSoon = pendingTasks.filter(t=>t.due_date && t.due_date>=today() && t.due_date<=new Date(Date.now()+3*86400000).toISOString().slice(0,10));
  const filteredCourses = courses.filter(c=>c.name.toLowerCase().includes(search.toLowerCase()));
  const allAttendanceCount = attendance.filter(a=>courses.some(c=>c.id===a.course_id));
  const presentCount = allAttendanceCount.filter(a=>a.status==='present').length;
  const absentTotal = allAttendanceCount.filter(a=>['absent','excused'].includes(a.status)).length;
  const nav = [
    {id:'dashboard',label:'Dashboard',icon:LayoutDashboard},
    {id:'courses',label:'Mata Kuliah',icon:BookOpen},
    {id:'attendance',label:'Absensi',icon:CalendarCheck},
    {id:'tasks',label:'Tugas',icon:ClipboardList},
    {id:'materials',label:'Arsip Materi',icon:FolderOpen},
    {id:'calendar',label:'Kalender',icon:CalendarDays},
  ];

  if (authLoading) return <div className="center-screen"><div className="loading-mark"><LoaderCircle className="spin" size={24}/></div><p>Menyiapkan ruang kuliahmu…</p></div>;
  if (!supabase) return <ConfigScreen />;
  if (!session) return <AuthScreen mode={authMode} setMode={setAuthMode} email={email} setEmail={setEmail} password={password} setPassword={setPassword} onSubmit={authSubmit} loading={loading} error={authError} notice={authNotice} />;

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav?'mobile-open':''}`}>
      <div className="brand"><div className="brand-icon"><BookMarked size={22}/></div><div><b>CampusSpace</b><small>Ruang kuliahmu</small></div><button className="icon-btn mobile-close" onClick={()=>setMobileNav(false)}><X size={18}/></button></div>
      <div className="semester-chip"><span className="tiny-dot"/><div><small>SEMESTER AKTIF</small><b>{semester?.name||'Belum diatur'}</b></div><button className="icon-btn" title="Tambah semester" onClick={()=>setModal({type:'semester'})}><Plus size={16}/></button></div>
      <nav className="main-nav">{nav.map(item=><button key={item.id} className={`nav-item ${page===item.id?'active':''}`} onClick={()=>{setPage(item.id);setActiveCourse(null);setMobileNav(false)}}><item.icon size={18}/><span>{item.label}</span>{item.id==='tasks'&&pendingTasks.length>0&&<em>{pendingTasks.length}</em>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="sidebar-tip"><Sparkles size={17}/><p>Pelan-pelan, satu tugas dalam satu waktu.</p></div><button className="nav-item" onClick={()=>setModal({type:'semester'})}><Settings size={18}/><span>Kelola Semester</span></button><button className="nav-item" onClick={signOut}><LogOut size={18}/><span>Keluar akun</span></button><div className="user-mini"><div className="avatar"><UserRound size={18}/></div><div className="user-meta"><b>{session.user.email?.split('@')[0]}</b><small>Akun pribadi</small></div><LockKeyhole size={15} className="lock-icon"/></div></div>
    </aside>
    {mobileNav&&<button className="scrim" onClick={()=>setMobileNav(false)} aria-label="Tutup menu"/>}
    <main className="main-area">
      <header className="topbar"><div className="top-left"><button className="icon-btn menu-toggle" onClick={()=>setMobileNav(true)}><Menu size={21}/></button><div className="crumb"><span>CampusSpace</span><ChevronRight size={14}/><b>{currentCourse?.name || nav.find(n=>n.id===page)?.label || 'Dashboard'}</b></div></div><div className="top-actions"><div className="top-date"><CalendarDays size={16}/>{new Date().toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short'})}</div><button className="icon-btn notification-btn" title="Peringatan"><Bell size={18}/>{(overdueTasks.length>0||courses.some(c=>absenceCount(c.id)>=2))&&<i/>}</button><div className="avatar small-avatar"><UserRound size={17}/></div></div></header>
      <div className="content">
        {notice&&<div className={`toast ${notice.startsWith('Gagal')||notice.startsWith('Belum')?'toast-error':''}`}><span>{notice}</span><button className="icon-btn" onClick={()=>setNotice('')}><X size={15}/></button></div>}
        {loading&&<div className="inline-loading"><LoaderCircle size={15} className="spin"/> Menyimpan atau memuat data…</div>}
        {currentCourse ? <CoursePage course={currentCourse} tab={courseTab} setTab={setCourseTab} setActiveCourse={setActiveCourse} setModal={setModal} attendance={courseAttendance(currentCourse.id)} absenceCount={absenceCount(currentCourse.id)} absenceLimit={semester?.absence_limit??3} tasks={courseTasks(currentCourse.id)} materials={courseMaterials(currentCourse.id)} notes={courseNotes(currentCourse.id)} grades={courseGrades(currentCourse.id)} onDeleteAttendance={(id)=>removeItem('attendance',id,attendance,setAttendance,'catatan absensi')} onDeleteTask={(id)=>removeItem('tasks',id,tasks,setTasks,'tugas')} onDeleteMaterial={async(m)=>{if(!window.confirm('Hapus materi ini?'))return;try{if(m.file_path) await supabase.storage.from('campus-files').remove([m.file_path]);await deleteRow('materials',m.id);setMaterials(materials.filter(x=>x.id!==m.id));msg('Materi dihapus.')}catch(e){msg(getErr(e))}}} onDeleteNote={(id)=>removeItem('notes',id,notes,setNotes,'catatan')} onDeleteGrade={(id)=>removeItem('grades',id,grades,setGrades,'nilai')} onOpenMaterial={uploadMaterialFile} onEditTask={(row)=>setModal({type:'task',row})} onEditNote={(row)=>setModal({type:'note',row})} onEditGrade={(row)=>setModal({type:'grade',row})} onEditAttendance={(row)=>setModal({type:'attendance',row,courseId:currentCourse.id})}/> :
          page==='dashboard' ? <Dashboard semester={semester} semesters={semesters} courses={courses} attendance={allAttendanceCount} presentCount={presentCount} absentTotal={absentTotal} absenceLimit={semester?.absence_limit??3} pendingTasks={pendingTasks} overdueTasks={overdueTasks} dueSoon={dueSoon} courseTasks={courseTasks} absenceCount={absenceCount} setPage={setPage} openCourse={(id)=>{setActiveCourse(id);setCourseTab('overview')}} setModal={setModal} /> :
          page==='courses' ? <CoursesPage courses={filteredCourses} search={search} setSearch={setSearch} setModal={setModal} openCourse={(id)=>{setActiveCourse(id);setCourseTab('overview')}} onEdit={(row)=>setModal({type:'course',row})} onDelete={(id)=>removeItem('courses',id,courses,setCourses,'mata kuliah')} /> :
          page==='attendance' ? <AttendancePage courses={courses} attendance={attendance.filter(a=>courses.some(c=>c.id===a.course_id))} absenceCount={absenceCount} absenceLimit={semester?.absence_limit??3} setModal={setModal} openCourse={(id)=>{setActiveCourse(id);setCourseTab('attendance')}} onEdit={(row)=>setModal({type:'attendance',row,courseId:row.course_id})} onDelete={(id)=>removeItem('attendance',id,attendance,setAttendance,'catatan absensi')} /> :
          page==='tasks' ? <TasksPage tasks={tasks.filter(t=>courses.some(c=>c.id===t.course_id))} courses={courses} setModal={setModal} onEdit={(row)=>setModal({type:'task',row})} onDelete={(id)=>removeItem('tasks',id,tasks,setTasks,'tugas')} /> :
          page==='materials' ? <MaterialsPage materials={materials.filter(m=>courses.some(c=>c.id===m.course_id))} courses={courses} setModal={setModal} onOpen={uploadMaterialFile} onDelete={async(m)=>{if(!window.confirm('Hapus materi ini?'))return;try{if(m.file_path) await supabase.storage.from('campus-files').remove([m.file_path]);await deleteRow('materials',m.id);setMaterials(materials.filter(x=>x.id!==m.id));msg('Materi dihapus.')}catch(e){msg(getErr(e))}}} /> :
          page==='calendar' ? <CalendarPage tasks={tasks.filter(t=>courses.some(c=>c.id===t.course_id))} courses={courses} attendance={attendance.filter(a=>courses.some(c=>c.id===a.course_id))} /> : null}
      </div>
      <footer className="footer"><span>CampusSpace <span className="footer-dot">✦</span> Ruang kuliahmu, tertata rapi.</span><span>Data pribadi · Sinkron lintas perangkat</span></footer>
    </main>
    {modal&&<Modal modal={modal} courses={courses} semester={semester} loading={loading} onClose={()=>setModal(null)} onSubmit={handleModalSubmit}/>}
  </div>;
}

function ConfigScreen() {
  return <div className="auth-layout"><div className="auth-art"><div className="art-orb orb-one"/><div className="art-orb orb-two"/><div className="auth-brand"><div className="brand-icon large"><BookMarked size={27}/></div><span>CampusSpace</span></div><div className="art-copy"><span className="eyebrow">YOUR PERSONAL ACADEMIC SPACE</span><h1>Semua urusan kuliah,<br/><i>lebih tertata.</i></h1><p>Absensi, tugas, materi, dan catatan dalam satu ruang pribadi.</p></div><div className="art-bottom">Belajar teratur, jalani semester dengan tenang.</div></div><div className="auth-panel"><div className="auth-card"><div className="auth-icon"><Settings size={22}/></div><h2>Hubungkan Supabase dulu</h2><p className="muted-text">Website sudah siap, tetapi koneksi database belum diatur. Tambahkan dua environment variables ini di pengaturan deploy Netlify, lalu deploy ulang.</p><div className="setup-code"><b>VITE_SUPABASE_URL</b><code>URL project Supabase</code><b>VITE_SUPABASE_ANON_KEY</b><code>Publishable / anon key</code></div><p className="muted-text small">Ikuti petunjuk di README.md dan jalankan file supabase.sql di Supabase SQL Editor. Jangan gunakan service_role key.</p></div></div></div>;
}
function AuthScreen({mode,setMode,email,setEmail,password,setPassword,onSubmit,loading,error,notice}) {
  return <div className="auth-layout"><div className="auth-art"><div className="art-orb orb-one"/><div className="art-orb orb-two"/><div className="auth-brand"><div className="brand-icon large"><BookMarked size={27}/></div><span>CampusSpace</span></div><div className="art-copy"><span className="eyebrow">YOUR PERSONAL ACADEMIC SPACE</span><h1>Semua urusan kuliah,<br/><i>lebih tertata.</i></h1><p>Absensi, tugas, materi, dan catatan dalam satu ruang pribadi.</p></div><div className="art-bottom">Belajar teratur, jalani semester dengan tenang.</div><div className="decor-card"><div className="decor-check"><CheckCircle2 size={17}/></div><div><b>Small steps, big progress.</b><small>Satu per satu, kamu pasti bisa.</small></div><Sparkles size={19}/></div></div><div className="auth-panel"><form className="auth-card" onSubmit={onSubmit}><div className="auth-icon"><BookOpen size={22}/></div><span className="eyebrow burgundy">{mode==='login'?'SELAMAT DATANG KEMBALI':'MULAI RUANG KULIAHMU'}</span><h2>{mode==='login'?'Masuk ke CampusSpace':'Buat akun pribadi'}</h2><p className="muted-text">{mode==='login'?'Lanjutkan mengatur semester dengan lebih tenang.':'Buat akun agar data kuliahmu tersimpan secara pribadi.'}</p>{error&&<div className="form-error">{error}</div>}{notice&&<div className="form-success">{notice}</div>}<label>Email</label><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="nama@email.com" required autoComplete="email"/><label>Password</label><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Minimal 6 karakter" required minLength={6} autoComplete={mode==='login'?'current-password':'new-password'}/><button className="btn-primary auth-submit" disabled={loading}>{loading?<LoaderCircle size={17} className="spin"/>:null}{mode==='login'?'Masuk ke akun':'Daftar sekarang'}<ArrowUpRight size={17}/></button><div className="auth-switch">{mode==='login'?'Belum punya akun?':'Sudah punya akun?'} <button type="button" onClick={()=>setMode(mode==='login'?'signup':'login')}>{mode==='login'?'Daftar':'Masuk'}</button></div><div className="privacy-note"><LockKeyhole size={14}/> Data hanya dapat diakses oleh akunmu.</div></form></div></div>;
}
function PageHeading({eyebrow,title,description,action,actionLabel='Tambah',icon:Icon=Plus}) {
  return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action&&<button className="btn-primary" onClick={action}><Icon size={17}/>{actionLabel}</button>}</div>;
}
function Dashboard({semester,semesters=[],courses,attendance,presentCount,absentTotal,absenceLimit,pendingTasks,overdueTasks,dueSoon,courseTasks,absenceCount,setPage,openCourse,setModal}) {
  const nextTasks=[...pendingTasks].sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).slice(0,5);
  const attendancePercent=attendance.length?Math.round(presentCount/attendance.length*100):0;
  return <><PageHeading eyebrow="RINGKASAN SEMESTER" title="Hai, semangat kuliah! ✦" description={`Selamat datang di ${semester?.name||'semester aktif'}. Yuk, rapikan satu per satu.`} action={()=>setModal({type:'course'})} actionLabel="Tambah mata kuliah"/><div className="welcome-banner"><div className="welcome-copy"><span className="welcome-tag"><Sparkles size={13}/> YOUR ACADEMIC SPACE</span><h2>Progress kecil hari ini,<br/><i>hasil besar nanti.</i></h2><p>Simpan materi, pantau tugas, dan jaga kehadiranmu tetap aman.</p></div><div className="welcome-illustration"><div className="ill-book"><BookOpen size={40}/></div><div className="ill-star star-a">✦</div><div className="ill-star star-b">✧</div><div className="ill-leaf">〰</div></div></div><div className="stats-grid"><StatCard icon={BookOpen} label="Mata kuliah" value={courses.length} sub="di semester aktif" tone="pink"/><StatCard icon={ClipboardList} label="Tugas aktif" value={pendingTasks.length} sub={overdueTasks.length?`${overdueTasks.length} melewati deadline`:'Tetap cek deadline ya'} tone="cream" alert={overdueTasks.length>0}/><StatCard icon={CalendarCheck} label="Kehadiran tercatat" value={presentCount} sub={`${attendancePercent}% dari catatan pertemuan`} tone="lavender"/><StatCard icon={AlertTriangle} label="Tidak hadir" value={absentTotal} sub="total alpa + izin" tone="peach" alert={absentTotal>0}/></div><div className="dashboard-grid"><section className="panel course-panel"><div className="panel-head"><div><h3>Mata kuliahmu</h3><p>Ruang belajar per mata kuliah</p></div><button className="text-link" onClick={()=>setPage('courses')}>Lihat semua <ChevronRight size={15}/></button></div>{courses.length===0?<EmptyState icon={BookOpen} title="Belum ada mata kuliah" text="Tambahkan mata kuliah untuk mulai mencatat absensi, tugas, dan materi." action={()=>setModal({type:'course'})} actionLabel="Tambah mata kuliah"/>:<div className="course-list">{courses.slice(0,5).map((c,i)=><button className="course-row" key={c.id} onClick={()=>openCourse(c.id)}><div className="course-monogram" style={{background:`${c.color||COURSE_COLORS[i%6]}18`,color:c.color||COURSE_COLORS[i%6]}}>{c.name.slice(0,1).toUpperCase()}</div><div className="course-row-main"><b>{c.name}</b><small>{c.day_of_week!==null&&c.day_of_week!==undefined?DAYS[c.day_of_week]:'Jadwal belum diatur'}{c.start_time?` · ${String(c.start_time).slice(0,5)}`:''}</small></div><div className="course-row-status"><span className={`mini-status ${absenceCount(c.id)>=3?'danger':absenceCount(c.id)>=2?'warning':'ok'}`}>{absenceCount(c.id)}/{semester?.absence_limit??3} absen</span><ChevronRight size={16}/></div></button>)}</div>}</section><section className="panel tasks-panel"><div className="panel-head"><div><h3>Yang perlu dikerjakan</h3><p>Prioritas dan deadline terdekat</p></div><button className="text-link" onClick={()=>setPage('tasks')}>Lihat semua <ChevronRight size={15}/></button></div>{nextTasks.length===0?<EmptyState icon={CheckCircle2} title="Semua terlihat terkendali" text="Belum ada tugas aktif. Tambahkan tugas saat dosen memberikan pekerjaan." action={()=>setModal({type:'task'})} actionLabel="Tambah tugas"/>:<div className="task-list">{nextTasks.map(t=><div className="task-row" key={t.id}><div className={`task-priority ${t.priority}`}><Circle size={13}/></div><div className="task-row-main"><b>{t.title}</b><small>{courses.find(c=>c.id===t.course_id)?.name||'Mata kuliah'} · {t.due_date?fmtDate(t.due_date):'Tanpa deadline'}</small></div><span className={`badge ${TASK_STATUS[t.status]?.cls}`}>{TASK_STATUS[t.status]?.label}</span></div>)}</div>}{(overdueTasks.length||dueSoon.length)>0&&<div className="deadline-callout"><AlertTriangle size={16}/><span>{overdueTasks.length?`${overdueTasks.length} tugas melewati deadline`: `${dueSoon.length} tugas deadline dalam 3 hari`}</span></div>}</section></div><section className="panel attendance-panel"><div className="panel-head"><div><h3>Jaga jatah absensimu</h3><p>Batas tidak hadir saat ini: {semester?.absence_limit??3} kali per mata kuliah</p></div><button className="text-link" onClick={()=>setPage('attendance')}>Buka absensi <ChevronRight size={15}/></button></div>{courses.length===0?<p className="muted-text">Tambahkan mata kuliah untuk mulai memantau absensi.</p>:<div className="absence-grid">{courses.map(c=>{const n=absenceCount(c.id),limit=semester?.absence_limit??3;return <button className="absence-item" key={c.id} onClick={()=>openCourse(c.id)}><div className="absence-top"><span>{c.name}</span><b className={n>=limit?'text-danger':n>=Math.max(1,limit-1)?'text-warning':''}>{n}/{limit}</b></div><div className="progress-track"><div className={`progress-fill ${n>=limit?'danger':n>=Math.max(1,limit-1)?'warning':''}`} style={{width:`${limit?Math.min(100,n/limit*100):0}%`}}/></div><small>{n>=limit?'Batas tercapai':n===limit-1?'Sisa toleransi 1 kali':`Sisa toleransi ${Math.max(0,limit-n)} kali`}</small></button>})}</div>}</section><section className="panel semester-history-panel"><div className="panel-head"><div><h3>Riwayat semester</h3><p>Semester sebelumnya tetap tersimpan saat kamu naik semester.</p></div><span className="history-count">{Math.max(0,semesters.filter(s=>!s.is_active).length)} semester lalu</span></div>{semesters.length<=1?<div className="history-empty"><div className="history-empty-icon">✦</div><div><b>Riwayatmu akan muncul di sini</b><p className="muted-text">Saat kamu membuat semester baru melalui Kelola Semester, semester sebelumnya akan tercatat di bagian ini.</p></div></div>:<div className="semester-history-list">{semesters.filter(s=>!s.is_active).slice().reverse().map(s=><div className="semester-history-row" key={s.id}><div className="history-book"><BookOpen size={18}/></div><div className="history-semester-meta"><b>{s.name}</b><small>{s.start_date?`Mulai ${fmtDate(s.start_date)}`:'Semester sebelumnya'}{s.end_date?` · Selesai ${fmtDate(s.end_date)}`:''}</small></div><span className="history-archived">Riwayat</span></div>)}</div>}</section></>;
}
function StatCard({icon:Icon,label,value,sub,tone,alert}) {return <div className={`stat-card ${tone}`}><div className="stat-top"><div className="stat-icon"><Icon size={19}/></div>{alert&&<span className="stat-alert"><AlertTriangle size={14}/></span>}</div><div className="stat-value">{value}</div><div className="stat-label">{label}</div><div className="stat-sub">{sub}</div></div>}
function EmptyState({icon:Icon,title,text,action,actionLabel}) {return <div className="empty-state"><div className="empty-icon"><Icon size={22}/></div><b>{title}</b><p>{text}</p>{action&&<button className="btn-outline small-btn" onClick={action}><Plus size={15}/>{actionLabel}</button>}</div>}
function CoursesPage({courses,search,setSearch,setModal,openCourse,onEdit,onDelete}) {return <><PageHeading eyebrow="RUANG BELAJAR" title="Mata kuliah" description="Setiap mata kuliah punya ruang sendiri untuk absensi, tugas, dan materi." action={()=>setModal({type:'course'})} actionLabel="Tambah mata kuliah"/><div className="toolbar"><div className="search-box"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Cari mata kuliah…"/></div><span className="muted-text">{courses.length} mata kuliah</span></div>{courses.length===0?<EmptyState icon={BookOpen} title="Belum ada mata kuliah" text="Mulai dengan menambahkan mata kuliah semester ini." action={()=>setModal({type:'course'})} actionLabel="Tambah mata kuliah"/>:<div className="courses-grid">{courses.map((c,i)=><div className="course-card" key={c.id}><div className="course-card-top"><div className="course-card-icon" style={{background:`${c.color||COURSE_COLORS[i%6]}18`,color:c.color||COURSE_COLORS[i%6]}}><BookOpen size={22}/></div><div className="course-card-actions"><button className="icon-btn" title="Edit" onClick={()=>setModal({type:'course',row:c})}><Pencil size={15}/></button><button className="icon-btn danger-hover" title="Hapus" onClick={()=>onDelete(c.id)}><Trash2 size={15}/></button></div></div><button className="course-card-title" onClick={()=>openCourse(c.id)}>{c.name}<ChevronRight size={17}/></button><p>{c.lecturer||'Nama dosen belum diisi'}</p><div className="course-card-meta"><span><CalendarDays size={14}/>{c.day_of_week!==null&&c.day_of_week!==undefined?DAYS[c.day_of_week]:'Jadwal belum diatur'}</span><span><Clock size={14}/>{c.start_time?String(c.start_time).slice(0,5):'--:--'}</span></div><button className="course-open" onClick={()=>openCourse(c.id)}>Buka ruang kuliah <ArrowUpRight size={15}/></button></div>)}</div>}</>}
function AttendancePage({courses,attendance,absenceCount,absenceLimit,setModal,openCourse,onEdit,onDelete}) {const [filter,setFilter]=useState('all');const filtered=attendance.filter(a=>filter==='all'||a.status===filter).sort((a,b)=>b.meeting_date.localeCompare(a.meeting_date));return <><PageHeading eyebrow="PANTAU KEHADIRAN" title="Absensi" description="Catat setiap pertemuan agar jumlah ketidakhadiran tidak terlewat." action={()=>setModal({type:'attendance'})} actionLabel="Catat absensi"/><div className="stats-grid compact-stats"><StatCard icon={CalendarCheck} label="Total catatan" value={attendance.length} sub="semua mata kuliah" tone="pink"/><StatCard icon={CheckCircle2} label="Hadir" value={attendance.filter(a=>a.status==='present').length} sub="pertemuan tercatat" tone="cream"/><StatCard icon={AlertTriangle} label="Alpa + izin" value={attendance.filter(a=>['absent','excused'].includes(a.status)).length} sub={`batas ${absenceLimit} kali per matkul`} tone="peach"/></div><section className="panel"><div className="panel-head"><div><h3>Riwayat absensi</h3><p>Setiap mata kuliah dihitung secara terpisah</p></div><select className="filter-select" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Semua status</option><option value="present">Hadir</option><option value="absent">Alpa</option><option value="excused">Izin</option><option value="sick">Sakit</option></select></div>{filtered.length===0?<EmptyState icon={CalendarCheck} title="Belum ada catatan absensi" text="Tambahkan catatan setiap selesai mengikuti pertemuan kuliah." action={()=>setModal({type:'attendance'})} actionLabel="Catat absensi"/>:<div className="table-wrap"><table><thead><tr><th>Tanggal</th><th>Mata kuliah</th><th>Pertemuan</th><th>Status</th><th>Keterangan</th><th></th></tr></thead><tbody>{filtered.map(a=><tr key={a.id}><td>{fmtDate(a.meeting_date)}</td><td><button className="table-link" onClick={()=>openCourse(a.course_id)}>{courses.find(c=>c.id===a.course_id)?.name||'Mata kuliah'}</button></td><td>{a.meeting_number||'—'}</td><td><span className={`badge ${STATUS[a.status]?.cls}`}>{STATUS[a.status]?.label}</span></td><td className="table-note">{a.note||'—'}</td><td><div className="row-actions"><button className="icon-btn" onClick={()=>onEdit(a)} title="Edit"><Pencil size={15}/></button><button className="icon-btn danger-hover" onClick={()=>onDelete(a.id)} title="Hapus"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>}</section><div className="notice-card"><AlertTriangle size={18}/><div><b>Catatan kebijakan absensi</b><p>Saat ini, status Alpa dan Izin memakai toleransi. Status Sakit tidak dihitung sebagai alpa. Sesuaikan dengan aturan dosen atau kampusmu.</p></div></div></>}
function TasksPage({tasks,courses,setModal,onEdit,onDelete}) {const [filter,setFilter]=useState('all');const rows=tasks.filter(t=>filter==='all'||t.status===filter).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));return <><PageHeading eyebrow="DAFTAR PEKERJAAN" title="Tugas kuliah" description="Simpan semua tugas berdasarkan mata kuliah, status, prioritas, dan deadline." action={()=>setModal({type:'task'})} actionLabel="Tambah tugas"/><div className="task-summary"><div><b>{tasks.filter(t=>!['done','submitted'].includes(t.status)).length}</b><span>Belum tuntas</span></div><div><b>{tasks.filter(t=>t.status==='done').length}</b><span>Selesai</span></div><div><b>{tasks.filter(t=>t.status==='submitted').length}</b><span>Dikumpulkan</span></div><div><b>{tasks.filter(t=>t.due_date&&t.due_date<today()&&!['done','submitted'].includes(t.status)).length}</b><span>Terlambat</span></div></div><section className="panel"><div className="panel-head"><div><h3>Semua tugas</h3><p>Perbarui status setelah mengerjakan atau mengumpulkan</p></div><select className="filter-select" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Semua status</option>{Object.entries(TASK_STATUS).map(([k,v])=><option value={k} key={k}>{v.label}</option>)}</select></div>{rows.length===0?<EmptyState icon={ClipboardList} title="Belum ada tugas" text="Catat tugas yang diberikan dosen agar tidak ada yang terlewat." action={()=>setModal({type:'task'})} actionLabel="Tambah tugas"/>:<div className="table-wrap"><table><thead><tr><th>Tugas</th><th>Mata kuliah</th><th>Deadline</th><th>Prioritas</th><th>Status</th><th></th></tr></thead><tbody>{rows.map(t=><tr key={t.id}><td><b>{t.title}</b>{t.description&&<small className="table-sub">{t.description}</small>}</td><td>{courses.find(c=>c.id===t.course_id)?.name||'Mata kuliah'}</td><td className={t.due_date&&t.due_date<today()&&!['done','submitted'].includes(t.status)?'text-danger':''}>{fmtDate(t.due_date)}</td><td><span className={`priority-label ${t.priority}`}>{t.priority==='high'?'Tinggi':t.priority==='low'?'Rendah':'Sedang'}</span></td><td><button className={`badge ${TASK_STATUS[t.status]?.cls} status-button`} onClick={()=>onEdit(t)}>{TASK_STATUS[t.status]?.label} <Pencil size={11}/></button></td><td><div className="row-actions"><button className="icon-btn" onClick={()=>onEdit(t)} title="Edit"><Pencil size={15}/></button><button className="icon-btn danger-hover" onClick={()=>onDelete(t.id)} title="Hapus"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>}</section></>}
function MaterialsPage({materials,courses,setModal,onOpen,onDelete}) {return <><PageHeading eyebrow="PERPUSTAKAAN PRIBADI" title="Arsip materi" description="Kumpulan PDF, slide, dan dokumen kuliah yang tersusun berdasarkan mata kuliah." action={()=>setModal({type:'material'})} actionLabel="Upload materi" icon={Upload}/>{materials.length===0?<EmptyState icon={FolderOpen} title="Arsip masih kosong" text="Unggah materi dosen, lalu beri nomor pertemuan dan keterangan supaya mudah ditemukan." action={()=>setModal({type:'material'})} actionLabel="Upload materi"/>:<div className="materials-grid">{materials.map(m=><div className="material-card" key={m.id}><div className="file-preview"><FileText size={28}/><span>{(m.file_name.split('.').pop()||'FILE').toUpperCase()}</span></div><div className="material-info"><span className="material-course">{courses.find(c=>c.id===m.course_id)?.name||'Mata kuliah'}</span><h3>{m.title}</h3><p>{m.description||'Belum ada keterangan.'}</p><div className="material-meta">{m.meeting_number?`Pertemuan ${m.meeting_number}`:'Pertemuan belum diisi'} · {fmtDate(m.material_date)}</div><div className="material-actions"><button className="btn-outline" onClick={()=>onOpen(m)}><ExternalLink size={15}/> Buka file</button><button className="icon-btn danger-hover" onClick={()=>onDelete(m)} title="Hapus materi"><Trash2 size={16}/></button></div></div></div>)}</div>}</>}
function CalendarPage({tasks,courses,attendance}) {const [month,setMonth]=useState(new Date(new Date().getFullYear(),new Date().getMonth(),1));const y=month.getFullYear(),m=month.getMonth();const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();const events={};tasks.forEach(t=>{if(t.due_date){(events[t.due_date]??=[]).push({type:'task',label:t.title,course:courses.find(c=>c.id===t.course_id)?.name})}});attendance.forEach(a=>{(events[a.meeting_date]??=[]).push({type:'attendance',label:`Absensi: ${STATUS[a.status]?.label}`,course:courses.find(c=>c.id===a.course_id)?.name})});const [selected,setSelected]=useState(today());const monthLabel=month.toLocaleDateString('id-ID',{month:'long',year:'numeric'});return <><PageHeading eyebrow="JADWAL DAN TENGGAT" title="Kalender akademik" description="Lihat deadline tugas dan tanggal absensi dalam satu tampilan."/><section className="panel calendar-panel"><div className="calendar-head"><button className="icon-btn" onClick={()=>setMonth(new Date(y,m-1,1))}><ChevronRight className="rotate-180" size={19}/></button><h3>{monthLabel}</h3><button className="icon-btn" onClick={()=>setMonth(new Date(y,m+1,1))}><ChevronRight size={19}/></button><button className="btn-outline today-btn" onClick={()=>{setMonth(new Date(new Date().getFullYear(),new Date().getMonth(),1));setSelected(today())}}>Hari ini</button></div><div className="calendar-grid">{['Min','Sen','Sel','Rab','Kam','Jum','Sab'].map(d=><div className="calendar-weekday" key={d}>{d}</div>)}{Array.from({length:first},(_,i)=><div key={`e${i}`} className="calendar-day blank"/>)}{Array.from({length:days},(_,i)=>{const day=i+1,date=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;return <button key={date} className={`calendar-day ${selected===date?'selected':''} ${date===today()?'is-today':''}`} onClick={()=>setSelected(date)}><span>{day}</span>{events[date]?.length>0&&<i className={events[date].some(e=>e.type==='task')?'has-task':'has-attendance'}/>}</button>})}</div><div className="calendar-legend"><span><i className="has-task"/> Deadline tugas</span><span><i className="has-attendance"/> Catatan absensi</span></div></section><section className="panel selected-events"><div className="panel-head"><div><h3>{fmtDate(selected)}</h3><p>Agenda pada tanggal terpilih</p></div></div>{(events[selected]||[]).length===0?<p className="muted-text empty-inline">Tidak ada agenda tercatat pada tanggal ini.</p>:(events[selected]||[]).map((e,i)=><div className="event-row" key={i}><div className={`event-icon ${e.type}`}><CalendarDays size={17}/></div><div><b>{e.label}</b><small>{e.course}</small></div><span className={`badge ${e.type==='task'?'amber':'blue'}`}>{e.type==='task'?'Deadline':'Absensi'}</span></div>)}</section></>}
function CoursePage({course,tab,setTab,setActiveCourse,setModal,attendance,absenceCount,absenceLimit,tasks,materials,notes,grades,onDeleteAttendance,onDeleteTask,onDeleteMaterial,onDeleteNote,onDeleteGrade,onOpenMaterial,onEditTask,onEditNote,onEditGrade,onEditAttendance}) {const tabs=[['overview','Ringkasan'],['attendance','Absensi'],['tasks','Tugas'],['materials','Materi'],['notes','Catatan'],['grades','Nilai']];const [noteSearch,setNoteSearch]=useState('');const [quickStatus,setQuickStatus]=useState('present');return <><button className="back-link" onClick={()=>setActiveCourse(null)}><ChevronRight className="rotate-180" size={16}/> Kembali ke mata kuliah</button><div className="course-detail-hero"><div className="course-detail-icon" style={{background:`${course.color}20`,color:course.color}}><BookOpen size={28}/></div><div className="course-detail-copy"><span className="eyebrow">RUANG MATA KULIAH</span><h1>{course.name}</h1><p>{course.lecturer||'Dosen belum diisi'}{course.room?` · ${course.room}`:''}</p><div className="course-detail-time"><CalendarDays size={14}/>{course.day_of_week!==null&&course.day_of_week!==undefined?DAYS[course.day_of_week]:'Jadwal belum diatur'}{course.start_time?` · ${String(course.start_time).slice(0,5)}${course.end_time?`–${String(course.end_time).slice(0,5)}`:''}`:''}</div></div><button className="btn-outline edit-course-btn" onClick={()=>setModal({type:'course',row:course})}><Pencil size={15}/> Edit mata kuliah</button></div><div className="course-tabs">{tabs.map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}{id==='tasks'&&tasks.filter(t=>!['done','submitted'].includes(t.status)).length>0&&<span>{tasks.filter(t=>!['done','submitted'].includes(t.status)).length}</span>}</button>)}</div>{tab==='overview'?<><div className="stats-grid course-stats"><StatCard icon={CalendarCheck} label="Tidak hadir" value={`${absenceCount}/${absenceLimit}`} sub={absenceCount>=absenceLimit?'Batas tercapai':`Sisa ${absenceLimit-absenceCount} kali`} tone="peach" alert={absenceCount>=absenceLimit}/><StatCard icon={ClipboardList} label="Tugas aktif" value={tasks.filter(t=>!['done','submitted'].includes(t.status)).length} sub={`${tasks.length} tugas tercatat`} tone="pink"/><StatCard icon={FolderOpen} label="Materi tersimpan" value={materials.length} sub="file di arsip" tone="cream"/><StatCard icon={GraduationCap} label="Komponen nilai" value={grades.length} sub="nilai tercatat" tone="lavender"/></div><div className="course-detail-grid"><section className="panel"><div className="panel-head"><div><h3>Catat absensi hari ini</h3><p>Catatan untuk {course.name}</p></div></div><div className="quick-attendance"><label>Status kehadiran</label><div className="quick-statuses">{Object.entries(STATUS).map(([key,s])=><button key={key} className={`quick-status ${quickStatus===key?'selected':''}`} onClick={()=>setQuickStatus(key)}><span className={`status-dot ${s.cls}`}/>{s.label}</button>)}</div><button className="btn-primary full-btn" onClick={()=>setModal({type:'attendance',courseId:course.id,defaults:{meeting_date:today(),status:quickStatus}})}><Plus size={16}/> Simpan catatan absensi</button></div></section><section className="panel"><div className="panel-head"><div><h3>Deadline terdekat</h3><p>Tugas yang perlu diperhatikan</p></div><button className="text-link" onClick={()=>setTab('tasks')}>Semua tugas <ChevronRight size={15}/></button></div>{tasks.filter(t=>!['done','submitted'].includes(t.status)).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).slice(0,4).map(t=><div className="compact-task" key={t.id}><div><b>{t.title}</b><small>{fmtDate(t.due_date)}</small></div><span className={`badge ${TASK_STATUS[t.status]?.cls}`}>{TASK_STATUS[t.status]?.label}</span></div>)}{tasks.filter(t=>!['done','submitted'].includes(t.status)).length===0&&<p className="muted-text">Belum ada tugas aktif.</p>}</section></div></>:tab==='attendance'?<section className="panel"><div className="panel-head"><div><h3>Riwayat absensi</h3><p>{absenceCount} dari {absenceLimit} toleransi terpakai (Alpa + Izin)</p></div><button className="btn-primary" onClick={()=>setModal({type:'attendance',courseId:course.id})}><Plus size={16}/> Catat absensi</button></div><div className="absence-alert-bar"><div className="progress-track"><div className={`progress-fill ${absenceCount>=absenceLimit?'danger':absenceCount>=absenceLimit-1?'warning':''}`} style={{width:`${absenceLimit?Math.min(100,absenceCount/absenceLimit*100):0}%`}}/></div><b>{absenceCount>=absenceLimit?'Batas toleransi tercapai':`Sisa ${Math.max(0,absenceLimit-absenceCount)} kali`}</b></div>{attendance.length===0?<EmptyState icon={CalendarCheck} title="Belum ada riwayat" text="Tambahkan tanggal dan status setiap pertemuan." action={()=>setModal({type:'attendance',courseId:course.id})} actionLabel="Catat absensi"/>:<div className="table-wrap"><table><thead><tr><th>Tanggal</th><th>Pertemuan</th><th>Status</th><th>Keterangan</th><th></th></tr></thead><tbody>{[...attendance].sort((a,b)=>b.meeting_date.localeCompare(a.meeting_date)).map(a=><tr key={a.id}><td>{fmtDate(a.meeting_date)}</td><td>{a.meeting_number||'—'}</td><td><span className={`badge ${STATUS[a.status]?.cls}`}>{STATUS[a.status]?.label}</span></td><td>{a.note||'—'}</td><td><div className="row-actions"><button className="icon-btn" onClick={()=>onEditAttendance(a)}><Pencil size={15}/></button><button className="icon-btn danger-hover" onClick={()=>onDeleteAttendance(a.id)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>}</section>:tab==='tasks'?<section className="panel"><div className="panel-head"><div><h3>Tugas mata kuliah</h3><p>Kelola proses pengerjaan sampai dikumpulkan</p></div><button className="btn-primary" onClick={()=>setModal({type:'task',courseId:course.id})}><Plus size={16}/> Tambah tugas</button></div>{tasks.length===0?<EmptyState icon={ClipboardList} title="Belum ada tugas" text="Tambahkan tugas dan tentukan deadline-nya." action={()=>setModal({type:'task',courseId:course.id})} actionLabel="Tambah tugas"/>:<div className="detail-list">{tasks.map(t=><div className="detail-list-row" key={t.id}><div className="detail-file-icon"><ClipboardList size={19}/></div><div className="detail-row-copy"><b>{t.title}</b><p>{t.description||'Tanpa deskripsi'}</p><small>Deadline: {fmtDate(t.due_date)} · Prioritas {t.priority==='high'?'tinggi':t.priority==='low'?'rendah':'sedang'}</small></div><button className={`badge ${TASK_STATUS[t.status]?.cls} status-button`} onClick={()=>onEditTask(t)}>{TASK_STATUS[t.status]?.label} <Pencil size={11}/></button><button className="icon-btn danger-hover" onClick={()=>onDeleteTask(t.id)}><Trash2 size={15}/></button></div>)}</div>}</section>:tab==='materials'?<section className="panel"><div className="panel-head"><div><h3>Materi per pertemuan</h3><p>PDF, slide, dokumen, dan foto catatan</p></div><button className="btn-primary" onClick={()=>setModal({type:'material',courseId:course.id})}><Upload size={16}/> Upload materi</button></div>{materials.length===0?<EmptyState icon={FolderOpen} title="Belum ada materi" text="Unggah file lalu beri judul, nomor pertemuan, dan keterangan." action={()=>setModal({type:'material',courseId:course.id})} actionLabel="Upload materi"/>:<div className="detail-list">{materials.map(m=><div className="detail-list-row" key={m.id}><div className="detail-file-icon pdf"><FileText size={19}/></div><div className="detail-row-copy"><b>{m.title}</b><p>{m.description||'Tanpa keterangan'}</p><small>{m.meeting_number?`Pertemuan ${m.meeting_number} · `:''}{fmtDate(m.material_date)} · {m.file_name|| (m.material_url?'Tautan web':'Materi')}</small></div><button className="btn-outline" onClick={()=>onOpenMaterial(m)}><ExternalLink size={14}/> Buka</button><button className="icon-btn danger-hover" onClick={()=>onDeleteMaterial(m)}><Trash2 size={15}/></button></div>)}</div>}</section>:tab==='notes'?<section className="panel"><div className="panel-head"><div><h3>Catatan kuliah</h3><p>Rumus, penjelasan dosen, dan hal penting</p></div><button className="btn-primary" onClick={()=>setModal({type:'note',courseId:course.id})}><Plus size={16}/> Tambah catatan</button></div><div className="search-box note-search"><Search size={16}/><input value={noteSearch} onChange={e=>setNoteSearch(e.target.value)} placeholder="Cari catatan…"/></div>{notes.filter(n=>(n.title+' '+(n.content||'')).toLowerCase().includes(noteSearch.toLowerCase())).length===0?<EmptyState icon={NotebookPen} title="Belum ada catatan" text="Simpan poin penting dari setiap pertemuan." action={()=>setModal({type:'note',courseId:course.id})} actionLabel="Tambah catatan"/>:<div className="notes-grid">{notes.filter(n=>(n.title+' '+(n.content||'')).toLowerCase().includes(noteSearch.toLowerCase())).map(n=><div className="note-card" key={n.id}><div className="note-card-head"><NotebookPen size={17}/><div><button className="icon-btn" onClick={()=>onEditNote(n)}><Pencil size={14}/></button><button className="icon-btn danger-hover" onClick={()=>onDeleteNote(n.id)}><Trash2 size={14}/></button></div></div><h3>{n.title}</h3><p>{n.content||'Catatan kosong'}</p><small>Diperbarui {new Date(n.updated_at||n.created_at).toLocaleDateString('id-ID')}</small></div>)}</div>}</section>:<section className="panel"><div className="panel-head"><div><h3>Nilai dan komponen penilaian</h3><p>Catat nilai yang sudah keluar dan bobot penilaiannya</p></div><button className="btn-primary" onClick={()=>setModal({type:'grade',courseId:course.id})}><Plus size={16}/> Tambah nilai</button></div>{grades.length===0?<EmptyState icon={GraduationCap} title="Belum ada nilai" text="Catat nilai kuis, tugas, UTS, UAS, atau praktikum." action={()=>setModal({type:'grade',courseId:course.id})} actionLabel="Tambah nilai"/>:<div className="table-wrap"><table><thead><tr><th>Komponen</th><th>Nilai</th><th>Bobot</th><th>Keterangan</th><th></th></tr></thead><tbody>{grades.map(g=><tr key={g.id}><td><b>{g.title}</b></td><td>{g.score??'—'}</td><td>{g.weight!==null?`${g.weight}%`:'—'}</td><td>{g.note||'—'}</td><td><div className="row-actions"><button className="icon-btn" onClick={()=>onEditGrade(g)}><Pencil size={15}/></button><button className="icon-btn danger-hover" onClick={()=>onDeleteGrade(g.id)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>}{grades.some(g=>g.score!==null&&g.weight!==null)&&<div className="grade-summary"><span>Estimasi nilai berbobot (komponen yang sudah diisi)</span><b>{(grades.reduce((sum,g)=>sum+(g.score!==null&&g.weight!==null?Number(g.score)*Number(g.weight)/100:0),0)).toFixed(2)}</b></div>}</section>}</>}
function Modal({modal,courses,semester,loading,onClose,onSubmit}) {
  const [values,setValues]=useState(()=>({...modal.row,...modal.defaults,course_id:modal.row?.course_id||modal.courseId||'',name:modal.row?.name||(modal.type==='semester'?'Semester 1':''),title:modal.row?.title||'',meeting_date:modal.row?.meeting_date||today(),status:modal.row?.status||modal.defaults?.status||'present',priority:modal.row?.priority||'medium',taskStatus:modal.row?.status||'todo',absence_limit:semester?.absence_limit??3}));
  const [file,setFile]=useState(null);
  const set=(key,val)=>setValues(v=>({...v,[key]:val}));
  const types={
    course:{title:modal.row?'Edit mata kuliah':'Tambah mata kuliah',desc:'Buat ruang belajar untuk satu mata kuliah.',fields:['name','lecturer','room','day_of_week','start_time','end_time','color']},
    task:{title:modal.row?'Edit tugas':'Tambah tugas',desc:'Catat tugas dan tenggat pengumpulannya.',fields:['course_id','title','description','due_date','priority','status']},
    attendance:{title:modal.row?'Edit absensi':'Catat absensi',desc:'Satu catatan per mata kuliah untuk setiap tanggal.',fields:['course_id','meeting_date','meeting_number','status','note']},
    material:{title:'Tambah materi kuliah',desc:'Upload file atau simpan tautan materi. File privat, maksimal 20 MB.',fields:['course_id','title','meeting_number','material_date','description','file','material_url']},
    note:{title:modal.row?'Edit catatan':'Tambah catatan kuliah',desc:'Simpan poin penting dari pertemuan.',fields:['course_id','title','content']},
    grade:{title:modal.row?'Edit nilai':'Tambah nilai',desc:'Bobot gunakan angka persen, misalnya 20 untuk 20%.',fields:['course_id','title','score','weight','note']},
    semester:{title:semester?'Buat semester baru':'Atur semester aktif',desc:semester?'Semester sebelumnya tetap tersimpan. Semester baru akan menjadi semester aktif.':'Pilih semester yang sedang kamu jalani. CampusSpace tidak menentukan semester secara otomatis.',fields:['name','absence_limit','start_date','end_date']}
  };
  const config=types[modal.type];
  async function submit(e){e.preventDefault();await onSubmit({...values,file});}
  const labelMap={name:'Nama semester',absence_limit:'Batas tidak hadir per mata kuliah',start_date:'Tanggal mulai',end_date:'Tanggal selesai',lecturer:'Nama dosen',room:'Ruang kelas',day_of_week:'Hari kuliah',start_time:'Jam mulai',end_time:'Jam selesai',color:'Warna identitas',course_id:'Mata kuliah',title:'Judul',description:'Deskripsi / keterangan',due_date:'Deadline',priority:'Prioritas',status:'Status',meeting_date:'Tanggal pertemuan',meeting_number:'Nomor pertemuan',note:'Keterangan',material_date:'Tanggal materi',file:'Pilih file (opsional jika memakai link)',material_url:'Link materi (opsional jika upload file)',content:'Isi catatan',score:'Nilai (0–100)',weight:'Bobot (%)'};
  function renderField(k){
    const label=labelMap[k]||k;
    if(k==='course_id') return <div className="field" key={k}><label>{label} *</label><select required value={values[k]||''} onChange={e=>set(k,e.target.value)}><option value="">Pilih mata kuliah</option>{courses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>{courses.length===0&&<small className="field-help">Tambahkan mata kuliah terlebih dahulu.</small>}</div>;
    if(k==='description'||k==='note'||k==='content') return <div className="field full-field" key={k}><label>{label}</label><textarea rows={k==='content'?6:3} value={values[k]||''} onChange={e=>set(k,e.target.value)} placeholder={k==='content'?'Tulis catatan kuliah di sini…':'Tambahkan keterangan (opsional)'}/></div>;
    if(k==='file') return <div className="field full-field" key={k}><label>{label}</label><label className="file-drop"><Upload size={22}/><b>{file?file.name:'Klik untuk memilih file'}</b><span>PDF, Word, Excel, PowerPoint, gambar, ZIP, dan file lain · Maksimal 20 MB</span><input type="file" accept="*/*" onChange={e=>setFile(e.target.files?.[0]||null)}/></label></div>;
    if(k==='material_url') return <div className="field full-field" key={k}><label>{label}</label><input type="url" value={values[k]||''} onChange={e=>set(k,e.target.value)} placeholder="https://drive.google.com/... atau tautan lainnya"/><small className="field-help">Bisa memakai Google Drive, OneDrive, YouTube, atau tautan web lain. Pastikan akses tautannya sudah dibagikan.</small></div>;
    if(k==='day_of_week') return <div className="field" key={k}><label>{label}</label><select value={values[k]??''} onChange={e=>set(k,e.target.value)}><option value="">Belum diatur</option>{DAYS.map((d,i)=><option value={i} key={d}>{d}</option>)}</select></div>;
    if(k==='status'&&modal.type==='attendance') return <div className="field" key={k}><label>{label}</label><select value={values[k]||'present'} onChange={e=>set(k,e.target.value)}>{Object.entries(STATUS).map(([v,s])=><option value={v} key={v}>{s.label}</option>)}</select></div>;
    if(k==='status'&&modal.type==='task') return <div className="field" key={k}><label>{label}</label><select value={values[k]||'todo'} onChange={e=>set(k,e.target.value)}>{Object.entries(TASK_STATUS).map(([v,s])=><option value={v} key={v}>{s.label}</option>)}</select></div>;
    if(k==='priority') return <div className="field" key={k}><label>{label}</label><select value={values[k]||'medium'} onChange={e=>set(k,e.target.value)}><option value="low">Rendah</option><option value="medium">Sedang</option><option value="high">Tinggi</option></select></div>;
    if(k==='color') return <div className="field" key={k}><label>{label}</label><div className="color-options">{COURSE_COLORS.map(c=><button type="button" key={c} className={values[k]===c?'selected':''} style={{background:c}} onClick={()=>set(k,c)} aria-label={c}/>)}</div></div>;
    let type='text';if(['due_date','meeting_date','material_date','start_date','end_date'].includes(k))type='date';if(['start_time','end_time'].includes(k))type='time';if(['meeting_number','absence_limit','score','weight'].includes(k))type='number';
    return <div className="field" key={k}><label>{label}{['name','title','meeting_date'].includes(k)?' *':''}</label><input type={type} required={['name','title','meeting_date'].includes(k)} min={['score','weight'].includes(k)?0:undefined} max={['score','weight'].includes(k)?100:undefined} value={values[k]??''} onChange={e=>set(k,e.target.value)} placeholder={k==='meeting_number'?'Contoh: 1':''}/></div>;
  }
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modal-card" onSubmit={submit}><div className="modal-head"><div><span className="eyebrow">CAMPUSSPACE</span><h2>{config.title}</h2><p>{config.desc}</p></div><button type="button" className="icon-btn" onClick={onClose}><X size={19}/></button></div><div className="modal-fields">{config.fields.map(renderField)}</div><div className="modal-footer"><button type="button" className="btn-outline" onClick={onClose}>Batal</button><button className="btn-primary" disabled={loading||(modal.type!=='course'&&modal.type!=='semester'&&courses.length===0)}>{loading?<LoaderCircle size={16} className="spin"/>:<CheckCircle2 size={16}/>} Simpan</button></div></form></div>;
}
createRoot(document.getElementById('root')).render(<App />);
